import React,{useState,useEffect,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {BrowserRouter,Routes,Route,NavLink,useNavigate,useParams,Link} from 'react-router-dom';
import {LayoutDashboard,FolderKanban,Files,ScanSearch,ShieldCheck,GitCompareArrows,Workflow,TriangleAlert,ClipboardCheck,FileDown,Settings,Users,History,ArrowUpRight,ArrowRight,Plus,Search,Bell,ChevronDown,ChevronRight,LogOut,Upload,Check,CheckCheck,FileText,Activity,LoaderCircle,X,Sparkles,Menu,MessageSquare,Download,Play,Filter,Building2} from 'lucide-react';
import {ResponsiveContainer,BarChart,Bar,XAxis,YAxis,Tooltip,CartesianGrid,PieChart,Pie,Cell} from 'recharts';
import {api,download} from './api';
import './style.css';


const Context=React.createContext();
export function Badge({children}){const s=String(children||'');const tone=/Approved|Complete$|Accepted|Verified|Processed|Fulfilled|^ok$|Resolved/.test(s)?'green':/Discrepancy|Failed|Critical|High|error|Rejected/.test(s)?'red':/Review|Pending|Incomplete|Missing|Unmatched|Investigation|Medium/.test(s)?'amber':'blue';return <span className={`badge ${tone}`}><i/>{s}</span>;}
const Empty=({text='No records yet. Add evidence to get started.'})=><div className="empty"><Files size={30}/><h3>Nothing here yet</h3><p>{text}</p></div>;
const Spinner=()=> <div className="loading"><LoaderCircle className="spin"/> Loading workspace…</div>;
function useLoad(fn,deps=[]){const [data,setData]=useState(null),[error,setError]=useState(''),[tick,setTick]=useState(0);useEffect(()=>{let active=true;setError('');setData(null);fn().then(d=>active&&setData(d)).catch(e=>active&&setError(e.message));return()=>{active=false};},[...deps,tick]);return {data,error,reload:()=>setTick(t=>t+1)};}
function ErrorBox({error}){return error?<div role="alert" className="error"><TriangleAlert size={17}/>{error}</div>:null;}
function Modal({title,children,onClose}){return <div className="overlay" onClick={onClose}><section role="dialog" aria-modal="true" aria-label={title} className="modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button className="icon-btn" onClick={onClose} aria-label="Close"><X/></button></div>{children}</section></div>;}
function Title({eyebrow='AUDIT WORKSPACE',title,description,children}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>;}
function SourceRefs({refs=[]}){const {setPreview}=React.useContext(Context);return <div className="source-refs">{refs.filter(Boolean).map((r,i)=><button key={i} className="source-chip" onClick={()=>setPreview(r.document_id)}><FileText size={13}/>Doc #{r.document_id} · {r.section||r.section_reference||('Page '+(r.page||r.page_number||1))}</button>)}</div>;}
function Table({columns,rows,onRow,empty}){const [page,setPage]=useState(1);const size=8;useEffect(()=>setPage(1),[rows]);if(!rows?.length)return <Empty text={empty}/>;return <><div className="table-scroll"><table><thead><tr>{columns.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{rows.slice((page-1)*size,page*size).map((row,i)=><tr key={row.id||i} onClick={()=>onRow?.(row)} className={onRow?'clickable':''}>{columns.map(c=><td key={c.key}>{c.render?c.render(row):row[c.key]??'—'}</td>)}</tr>)}</tbody></table></div><div className="table-footer"><span>Showing {Math.min((page-1)*size+1,rows.length)}–{Math.min(page*size,rows.length)} of {rows.length} records</span><div><button disabled={page===1} onClick={()=>setPage(p=>p-1)}>Previous</button><span>{page} / {Math.ceil(rows.length/size)}</span><button disabled={page*size>=rows.length} onClick={()=>setPage(p=>p+1)}>Next</button></div></div></>;}
const palette=['#168b7d','#3c73d6','#7b6cbb','#d7a347','#79b3ac','#a3b6c9'];
function ChartBars({data,color='#168b7d'}){return data.length?<ResponsiveContainer width="100%" height={210}><BarChart data={data} margin={{left:-20,right:12,top:12,bottom:5}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e8edf0"/><XAxis dataKey="name" tick={{fontSize:10}} tickLine={false} axisLine={false}/><YAxis allowDecimals={false} tick={{fontSize:10}} tickLine={false} axisLine={false}/><Tooltip/><Bar dataKey="value" fill={color} radius={[5,5,0,0]} maxBarSize={36}/></BarChart></ResponsiveContainer>:<Empty text="Metrics appear after documents are uploaded."/>;}

function Login({onLogin}){const [email,setEmail]=useState('auditor@auditflow.demo'),[password,setPassword]=useState('AuditFlowDemo!2026'),[username,setUsername]=useState(''),[register,setRegister]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);setError('');try{if(register)await api('/auth/register',{method:'POST',body:{email,password,username}});const d=await api('/auth/login',{method:'POST',body:{email,password}});sessionStorage.setItem('auditflow-token',d.token);onLogin(d.user);}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="login"><div className="login-brand"><div className="brand"><span className="brand-icon"><Workflow/></span>AuditFlow<span>AI</span></div><div><div className="eyebrow">A CLEARER PATH FROM EVIDENCE TO INSIGHT</div><h1>Confidence starts<br/>with the evidence.</h1><p>Collect, connect and verify your audit evidence.<br/>One traceable workflow. Your professional judgment.</p><div className="login-pills"><span><ShieldCheck/>Rule-based verification</span><span><ScanSearch/>Source-linked retrieval</span></div></div><small>FINANCIAL AUDIT INTELLIGENCE / HUMAN REVIEW BY DESIGN</small></div><div className="login-form"><div className="eyebrow">WELCOME TO YOUR WORKSPACE</div><h2>{register?'Create your account':'Welcome back'}</h2><p>Sign in to continue your audit work.</p><ErrorBox error={error}/><form onSubmit={submit}>{register&&<label>Full name<input required value={username} onChange={e=>setUsername(e.target.value)}/></label>}<label>Email address<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<input type="password" required minLength={12} value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="primary wide" disabled={busy}>{busy?<LoaderCircle className="spin" size={17}/>:null}{register?'Create account':'Sign in to workspace'}<ArrowRight size={17}/></button></form><button className="text-btn" onClick={()=>{setRegister(!register);setError('')}}>{register?'Already have an account? Sign in':'Create an auditor account'}</button><div className="demo-info"><Sparkles size={18}/><div><b>Synthetic demo workspace</b><p>Use auditor, reviewer or admin @auditflow.demo.<br/>Password: AuditFlowDemo!2026</p></div></div></div></div>;}

const nav=[['OVERVIEW',[['/','Dashboard',LayoutDashboard],['/audits','Audit projects',FolderKanban]]],['EVIDENCE & ANALYSIS',[['/documents','Document repository',Files],['/search','AI audit assistant',ScanSearch],['/evidence','Evidence mapping',ClipboardCheck],['/verification','Verification',ShieldCheck],['/reconciliation','Reconciliation',GitCompareArrows],['/anomalies','Anomaly detection',Activity]]],['WORKFLOW',[['/agents','Agent workspace',Workflow],['/findings','Audit findings',TriangleAlert],['/review','Review & approvals',CheckCheck],['/reports','Reports',FileDown]]],['ADMINISTRATION',[['/users','Team members',Users],['/logs','Audit trail',History],['/settings','Settings',Settings]]]];
export function Shell(){const [user,setUser]=useState(null),[checking,setChecking]=useState(true),[auditId,setAuditId]=useState(sessionStorage.getItem('auditflow-audit')||''),[preview,setPreview]=useState(null),[mobile,setMobile]=useState(false),[refresh,setRefresh]=useState(0),[notice,setNotice]=useState('');useEffect(()=>{if(sessionStorage.getItem('auditflow-token'))api('/auth/me').then(setUser).catch(()=>setUser(null)).finally(()=>setChecking(false));else setChecking(false);const expired=()=>setUser(null);window.addEventListener('auth-expired',expired);return()=>window.removeEventListener('auth-expired',expired)},[]);const audits=useLoad(()=>user?api('/audits?per_page=100'):Promise.resolve({items:[]}),[user,refresh]);useEffect(()=>{if(!auditId&&audits.data?.items.length)setAuditId(String(audits.data.items[0].id));},[audits.data]);useEffect(()=>sessionStorage.setItem('auditflow-audit',auditId),[auditId]);useEffect(()=>{if(notice){const timer=setTimeout(()=>setNotice(''),5000);return()=>clearTimeout(timer)}},[notice]);const context={user,auditId,setAuditId,setPreview,refresh:()=>setRefresh(x=>x+1),notify:setNotice};if(checking)return <Spinner/>;if(!user)return <Login onLogin={setUser}/>;return <Context.Provider value={context}><div className="app"><aside className={mobile?'sidebar open':'sidebar'}><Link to="/" className="brand"><span className="brand-icon"><Workflow/></span>AuditFlow<span>AI</span></Link><div className="workspace-label"><span className="workspace-avatar">N</span><div>Audit workspace<small>Evidence intelligence</small></div><ChevronDown size={15}/></div><nav>{nav.map(([group,links])=><section key={group}><h4>{group}</h4>{links.filter(([path])=>user.role==='administrator'||!['/users','/logs'].includes(path)).map(([path,label,Icon])=><NavLink end={path==='/'} to={path} key={path} onClick={()=>setMobile(false)}><Icon size={18}/><span>{label}</span>{path==='/agents'&&<span className="nav-dot"/>}</NavLink>)}</section>)}</nav><div className="sidebar-note"><span><ShieldCheck size={17}/> Evidence you can trace</span><p>AI assists. Auditors decide.<br/>Every step stays accountable.</p></div><button className="profile" onClick={async()=>{await api('/auth/logout',{method:'POST'}).catch(()=>{});sessionStorage.clear();setAuditId('');setUser(null)}}><span className="avatar">{user.username.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span>{user.username}<small>{user.role}</small></span><LogOut size={16}/></button></aside><div className="main"><header className="topbar"><button className="icon-btn mobile-menu" aria-label="Open navigation" onClick={()=>setMobile(!mobile)}><Menu/></button><div className="breadcrumbs">Workspace <ChevronRight size={13}/><b>Financial audits</b></div><div className="top-actions"><span className="live-pill"><i/>Demo workspace</span><span className="top-divider"/><Link to="/notifications" className="icon-btn" aria-label="Notifications"><Bell size={18}/></Link><span className="avatar small">{user.username[0]}</span></div></header><div className="audit-select-bar"><Building2 size={15}/><span>ACTIVE AUDIT</span><select aria-label="Active audit" value={auditId} onChange={e=>setAuditId(e.target.value)}><option value="">Select a project</option>{audits.data?.items.map(a=><option key={a.id} value={a.id}>{a.project_name}</option>)}</select><span className="human-label"><ShieldCheck size={14}/> Human review enabled</span></div><main><Routes><Route path="/" element={<Dashboard/>}/><Route path="/audits" element={<Projects/>}/><Route path="/audits/:id" element={<AuditWorkspace/>}/><Route path="/documents" element={<Documents/>}/><Route path="/search" element={<SearchPage/>}/><Route path="/evidence" element={<Evidence/>}/><Route path="/verification" element={<Results type="verification"/>}/><Route path="/reconciliation" element={<Results type="reconciliation"/>}/><Route path="/anomalies" element={<Anomalies/>}/><Route path="/agents" element={<Agents/>}/><Route path="/findings" element={<Findings/>}/><Route path="/review" element={<Findings review/>}/><Route path="/reports" element={<Reports/>}/><Route path="/users" element={<UsersPage/>}/><Route path="/logs" element={<Logs/>}/><Route path="/settings" element={<SettingsPage/>}/><Route path="/notifications" element={<Notifications/>}/><Route path="*" element={<Empty text="This page does not exist."/>}/></Routes><footer className="app-footer"><span>AuditFlow AI <b>·</b> Evidence-driven auditing</span><span>All conclusions remain subject to professional review.</span></footer></main></div>{preview&&<DocumentPreview id={preview} onClose={()=>setPreview(null)}/>} {notice&&<div className="toast" role="status"><Check size={18}/>{notice}</div>}</div></Context.Provider>;}

function Dashboard(){const {data,error}=useLoad(()=>api('/dashboard/summary'));const ctx=React.useContext(Context);if(!data)return error?<ErrorBox error={error}/>:<Spinner/>;const coverage=data.requirements?Math.round(data.complete/data.requirements*100):0;return <><Title eyebrow="YOUR AUDIT, AT A GLANCE" title="Audit overview" description="A connected view of your evidence, findings and audit progress."><Link className="secondary" to="/reports"><FileDown size={16}/>View reports</Link><Link className="primary" to="/audits"><Plus size={17}/>New audit project</Link></Title><div className="insight-banner"><span className="insight-icon"><Sparkles size={21}/></span><div><b>From scattered documents to connected evidence.</b><p>Your evidence collection and verification workflow, in one place.</p></div><Link to="/agents">Open agent workspace <ArrowRight size={16}/></Link></div><div className="stats-grid">{[[FolderKanban,'Audit projects',data.projects,'Projects in your workspace','blue'],[Files,'Evidence documents',data.documents,`${data.processed} processed · ${data.pending} need attention`,'teal'],[ShieldCheck,'Verified checks',data.verified,'Deterministic checks passed','green'],[TriangleAlert,'Discrepancies',data.discrepancies,'Awaiting investigation','amber']].map(([Icon,label,value,note,color])=><div className="stat-card" key={label}><div><span>{label}</span><span className={`stat-icon ${color}`}><Icon size={19}/></span></div><strong>{value.toLocaleString()}</strong><small>{note}</small></div>)}</div><div className="dashboard-grid"><section className="panel progress-panel"><div className="panel-heading"><div><h2>Evidence coverage</h2><p>Reviewed evidence against audit requirements</p></div><Link to="/evidence"><ArrowUpRight size={18}/></Link></div><div className="coverage-layout"><div className="donut" style={{'--progress':`${coverage*3.6}deg`}}><div><strong>{coverage}%</strong><span>reviewed complete</span></div></div><div className="coverage-stats"><div><i className="dot teal"/><span>Reviewed complete</span><b>{data.complete}</b></div><div><i className="dot amber"/><span>Missing evidence</span><b>{data.missing}</b></div><div><i className="dot gray"/><span>Other review pending</span><b>{data.requirements-data.complete-data.missing}</b></div><div className="mini-note">{data.requirements} requirements across your audits</div></div></div><Link className="panel-bottom" to="/evidence">Review evidence mapping<ArrowRight size={15}/></Link></section><section className="panel"><div className="panel-heading"><div><h2>Verification activity</h2><p>Current checks by result</p></div><span className="subtle-tag">LIVE RECORDS</span></div><ChartBars data={Object.entries(data.verification).map(([name,value])=>({name:name.replace(' by Rule','').replace(' Detected',''),value}))}/></section><section className="panel projects-panel"><div className="panel-heading"><div><h2>Audit projects</h2><p>Your active engagements and evidence progress</p></div><Link className="text-link" to="/audits">View all <ArrowRight size={14}/></Link></div><Table rows={data.audit_progress} columns={[{key:'name',label:'AUDIT PROJECT',render:r=><Link className="project-name" to={`/audits/${r.id}`}><span className="project-icon"><FolderKanban size={17}/></span><span>{r.name}<small>#{String(r.id).padStart(4,'0')} · Financial audit</small></span></Link>},{key:'documents',label:'DOCUMENTS'},{key:'complete',label:'EVIDENCE COVERAGE',render:r=><div className="inline-progress"><div><i style={{width:`${r.requirements?r.complete/r.requirements*100:0}%`}}/></div><span>{r.complete}/{r.requirements}</span></div>},{key:'status',label:'STATUS',render:r=><Badge>{r.status}</Badge>},{key:'action',label:'',render:r=><Link to={`/audits/${r.id}`} aria-label={'Open '+r.name}><ArrowUpRight size={17}/></Link>}]} /></section><section className="panel"><div className="panel-heading"><div><h2>Document activity</h2><p>Uploads by month</p></div><Files size={18}/></div><ChartBars data={Object.entries(data.uploads).map(([name,value])=>({name,value}))} color="#7193bd"/></section><section className="panel"><div className="panel-heading"><div><h2>Document categories</h2><p>Evidence inventory distribution</p></div></div>{Object.entries(data.categories).map(([name,value],i)=><div className="category-row" key={name}><span><i style={{background:palette[i%palette.length]}}/>{name}</span><b>{value}</b></div>)}</section><section className="panel workflow-promo"><span className="promo-icon"><Workflow size={26}/></span><span className="eyebrow">8 SPECIALIZED AGENTS</span><h2>One coordinated<br/>audit workflow.</h2><p>Connect document intelligence, retrieval, verification and reporting with traceable execution logs.</p><Link className="secondary" to="/agents">Explore agent workspace<ArrowRight size={16}/></Link><small><ShieldCheck size={13}/> Human approval before finalization</small></section></div></>;}

function Projects(){const ctx=React.useContext(Context);const [q,setQ]=useState(''),[modal,setModal]=useState(false);const {data,error,reload}=useLoad(()=>api('/audits?per_page=100&q='+encodeURIComponent(q)),[q]);return <><Title title="Audit projects" description="Manage engagements, collect evidence and keep reviews moving."><button className="primary" onClick={()=>setModal(true)}><Plus size={17}/>Create audit</button></Title><section className="panel"><div className="toolbar"><div className="search-input"><Search size={16}/><input aria-label="Search projects" placeholder="Search audit projects…" value={q} onChange={e=>setQ(e.target.value)}/></div><span className="muted">{data?.total||0} projects</span></div><ErrorBox error={error}/>{data?<Table rows={data.items} columns={[{key:'project_name',label:'PROJECT',render:r=><Link className="text-link" to={`/audits/${r.id}`}>{r.project_name}</Link>},{key:'financial_year',label:'FINANCIAL YEAR'},{key:'audit_type',label:'TYPE'},{key:'audit_period_end',label:'PERIOD END'},{key:'status',label:'STATUS',render:r=><Badge>{r.status}</Badge>}]} />:<Spinner/>}</section>{modal&&<CreateAudit onClose={()=>setModal(false)} onDone={a=>{ctx.setAuditId(String(a.id));ctx.refresh();reload();setModal(false)}}/>}</>;}
function CreateAudit({onClose,onDone}){const [error,setError]=useState(''),[busy,setBusy]=useState(false);const users=useLoad(()=>api('/users'));async function submit(e){e.preventDefault();setBusy(true);try{const d=Object.fromEntries(new FormData(e.target));if(d.reviewer_id)d.reviewer_id=Number(d.reviewer_id);else delete d.reviewer_id;const result=await api('/audits',{method:'POST',body:d});onDone(result)}catch(e){setError(e.message)}finally{setBusy(false)}}return <Modal title="Create audit project" onClose={onClose}><p className="muted">Set the scope, then bring your supporting evidence into the workspace.</p><ErrorBox error={error}/><form onSubmit={submit}><label>Project name<input name="project_name" required placeholder="FY 2025-26 Financial Audit"/></label><label>Organization<input name="organization_name" required placeholder="Organization name"/></label><div className="form-grid"><label>Financial year<input name="financial_year" defaultValue="2025-26" required/></label><label>Audit type<select name="audit_type">{['Financial statement audit','Internal audit','Expense audit','Revenue audit','Payroll audit','Compliance audit','Transaction audit'].map(t=><option key={t}>{t}</option>)}</select></label><label>Period start<input type="date" name="audit_period_start" defaultValue="2025-04-01" required/></label><label>Period end<input type="date" name="audit_period_end" defaultValue="2026-03-31" required/></label></div><label>Independent reviewer<select name="reviewer_id"><option value="">Assign later</option>{users.data?.items.filter(u=>['reviewer','administrator'].includes(u.role)).map(u=><option key={u.id} value={u.id}>{u.username}</option>)}</select></label><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?'Creating…':'Create project'}<ArrowRight size={16}/></button></div></form></Modal>;}
function AuditWorkspace(){const {id}=useParams();const ctx=React.useContext(Context);const {data,error}=useLoad(()=>api('/audits/'+id),[id]);useEffect(()=>{ctx.setAuditId(id)},[id]);if(!data)return error?<ErrorBox error={error}/>:<Spinner/>;return <><Title title={data.project_name} description={`${data.organization.organization_name} · ${data.financial_year}`}><Badge>{data.status}</Badge></Title><div className="scope-banner"><Building2/><div><b>{data.audit_type}</b><p>{data.audit_period_start} → {data.audit_period_end}</p></div></div><div className="action-grid">{[['/documents',Upload,'Collect evidence','Upload documents and inspect extracted source data.'],['/evidence',ClipboardCheck,'Map requirements','Connect the audit objectives with supporting evidence.'],['/agents',Workflow,'Run audit workflow','Coordinate eight specialized processing agents.'],['/review',CheckCheck,'Review findings','Investigate discrepancies and document decisions.'],['/reports',FileDown,'Prepare reports','Export a traceable PDF or Excel evidence snapshot.'],['/settings',Settings,'Configure checks','Set reconciliation tolerances and matching windows.']].map(([path,Icon,title,text])=><Link className="panel action-card" key={path} to={path}><Icon/><h3>{title}</h3><p>{text}</p><ArrowRight size={18}/></Link>)}</div></>;}

function Documents(){const ctx=React.useContext(Context);const [category,setCategory]=useState(''),[upload,setUpload]=useState(false),[error,setError]=useState(''),[search,setSearch]=useState('');const settings=useLoad(()=>api('/settings'));const docs=useLoad(()=>ctx.auditId?api(`/documents?audit_id=${ctx.auditId}&per_page=100&category=${encodeURIComponent(category)}`):Promise.resolve({items:[]}),[ctx.auditId,category]);return <><Title title="Document repository" description="Original evidence, preserved with its provenance and version history."><button className="primary" disabled={!ctx.auditId} onClick={()=>setUpload(true)}><Upload size={16}/>Upload documents</button></Title><div className="notice-inline"><ShieldCheck size={17}/> Originals are preserved. Replacement uploads create a new version; prior versions remain traceable.</div><section className="panel"><div className="toolbar"><div className="search-input"><Search size={16}/><input aria-label="Search documents" placeholder="Search documents…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="Category filter" value={category} onChange={e=>setCategory(e.target.value)}><option value="">All categories</option>{settings.data?.categories.map(c=><option key={c}>{c}</option>)}</select></div><ErrorBox error={error||docs.error}/>{docs.data?<Table rows={docs.data.items.filter(d=>d.document_name.toLowerCase().includes(search.toLowerCase()))} columns={[{key:'document_name',label:'DOCUMENT',render:d=><button className="file-name" onClick={()=>ctx.setPreview(d.id)}><span className="file-icon"><FileText size={19}/></span><span>{d.document_name}<small>Doc #{d.id} · Version {d.file_version}</small></span></button>},{key:'document_type',label:'CATEGORY'},{key:'processing_status',label:'PROCESSING',render:d=><Badge>{d.processing_status}</Badge>},{key:'created_at',label:'UPLOADED',render:d=>d.created_at.slice(0,10)},{key:'actions',label:'ACTIONS',render:d=><div className="row-actions"><button title="Download original" className="icon-btn" onClick={()=>download(`/documents/${d.id}/download`,d.document_name).catch(e=>setError(e.message))}><Download size={16}/></button><button className="text-btn" onClick={async()=>{if(!confirm('Archive this document? The original remains preserved.'))return;try{await api('/documents/'+d.id,{method:'DELETE'});docs.reload()}catch(e){setError(e.message)}}}>Archive</button></div>}]} empty="Select an audit and upload its financial documents."/>:<Spinner/>}</section>{upload&&<UploadModal categories={settings.data?.categories||[]} onClose={()=>setUpload(false)} onDone={()=>{docs.reload();ctx.refresh()}}/>}</>;}
function UploadModal({categories,onClose,onDone}){const ctx=React.useContext(Context);const [files,setFiles]=useState([]),[category,setCategory]=useState('Auto'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[result,setResult]=useState(null),[progress,setProgress]=useState(0);async function submit(e){e.preventDefault();setBusy(true);setError('');const form=new FormData();form.append('audit_id',ctx.auditId);form.append('category',category);const mappings=Object.fromEntries([...new FormData(e.currentTarget)].filter(([k,v])=>k.startsWith('map_')&&String(v).trim()).map(([k,v])=>[String(v).trim(),k.slice(4)]));form.append('column_mapping',JSON.stringify(mappings));files.forEach(f=>form.append('files',f));try{const data=await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/documents/bulk-upload');xhr.setRequestHeader('Authorization','Bearer '+sessionStorage.getItem('auditflow-token'));xhr.upload.onprogress=e=>{if(e.lengthComputable)setProgress(Math.round(e.loaded/e.total*100))};xhr.onload=()=>{try{const data=JSON.parse(xhr.responseText);xhr.status<300?resolve(data):reject(new Error(data.error))}catch{reject(new Error('Upload failed'))}};xhr.onerror=()=>reject(new Error('Network error'));xhr.send(form)});setResult(data);onDone()}catch(e){setError(e.message)}finally{setBusy(false)}}return <Modal title="Upload audit evidence" onClose={onClose}><ErrorBox error={error}/><form onSubmit={submit}><label className="dropzone"><Upload size={28}/><b>Choose files to upload</b><span>PDF, DOCX, XLSX, CSV, TXT, JPG, PNG or ZIP</span><small>See Settings for the file size limit · 30 files per upload</small><input aria-label="Evidence files" type="file" multiple accept=".pdf,.docx,.xlsx,.csv,.txt,.jpg,.jpeg,.png,.zip" onChange={e=>{setFiles([...e.target.files]);setResult(null)}}/></label>{files.map((f,i)=><div className="upload-file" key={i}><FileText size={16}/>{f.name}<small>{(f.size/1024).toFixed(0)} KB</small></div>)}<label>Evidence category<select value={category} onChange={e=>setCategory(e.target.value)}><option>Auto</option>{categories.map(c=><option key={c}>{c}</option>)}</select></label><details className='import-mapping'><summary>Map custom CSV / Excel column names</summary><p>Leave blank to use standard headers or automatic aliases.</p><div className='form-grid'>{['reference','date','amount','currency','invoice_number'].map(field=><label key={field}>{field.replace('_',' ')} column<input name={'map_'+field} placeholder={'Source header for '+field}/></label>)}</div></details>{busy&&<><div className="progress-track"><i style={{width:progress+'%'}}/></div><p className="muted">{progress<100?`Uploading ${progress}%`:'Extracting and indexing documents…'}</p></>}{result&&<div className="upload-results">{result.items.map(d=><div key={d.id}><span>{d.document_name}</span><Badge>{d.processing_status}</Badge>{d.processing_errors&&<p className="error-text">{d.processing_errors}</p>}</div>)}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Close</button><button className="primary" disabled={busy||!files.length}>{busy?'Processing…':'Upload & index'}<ArrowRight size={16}/></button></div></form></Modal>;}
function DocumentPreview({id,onClose}){const {data,error}=useLoad(()=>Promise.all([api('/documents/'+id),api(`/documents/${id}/extracted-text`)]).then(([doc,text])=>({doc,text})),[id]);const [versions,setVersions]=useState(false);return <Modal title="Evidence source viewer" onClose={onClose}><ErrorBox error={error}/>{data?<><div className="document-heading"><FileText/><div><h3>{data.doc.document_name}</h3><span>Document #{id} · v{data.doc.file_version} · {data.doc.document_type}</span></div><Badge>{data.doc.processing_status}</Badge></div><div className="metadata"><span>SHA-256</span><code>{data.doc.file_hash}</code><span>Extraction</span><b>{data.doc.extraction_method||'Unavailable'}</b><span>Malware scan</span><b>{data.doc.metadata_json?.malware_scan}</b></div>{data.doc.previous_version_id&&<p>Prior version: document #{data.doc.previous_version_id}</p>}<ErrorBox error={data.doc.processing_errors}/><h3>Extracted source text</h3><div className="extracted-text">{data.text.chunks.map(c=><section key={c.id}><b>{c.section_reference}{c.page_number?' · Page '+c.page_number:''}</b><pre>{c.chunk_text}</pre></section>)}</div><div className="modal-actions"><span className="muted">{data.text.records.length} structured rows extracted</span><button className="secondary" onClick={()=>download(`/documents/${id}/download`,data.doc.document_name)}><Download size={16}/>Download original</button></div></>:<Spinner/>}</Modal>;}

function SearchPage(){const ctx=React.useContext(Context);const [query,setQuery]=useState(''),[messages,setMessages]=useState([]),[busy,setBusy]=useState(false),[error,setError]=useState('');useEffect(()=>setMessages([]),[ctx.auditId]);async function submit(e,text){e?.preventDefault();const value=text||query;if(!value.trim()||!ctx.auditId)return;setBusy(true);setError('');setQuery('');try{const data=await api('/rag/query',{method:'POST',body:{audit_id:Number(ctx.auditId),query:value,top_k:5}});setMessages(m=>[...m,{query:value,...data}])}catch(e){setError(e.message)}finally{setBusy(false)}}return <><Title title="AI audit assistant" description="Search your audit evidence with a source reference behind every passage."><span className="mode-tag"><i/>Local extractive mode</span></Title><section className="panel assistant"><div className="assistant-intro"><span className="assistant-mark"><ScanSearch size={30}/></span><h2>Start with a question.<br/>Follow it to the evidence.</h2><p>Retrieve source passages from the active audit's documents.<br/>Local mode returns evidence excerpts for your interpretation.</p><div className="suggestions">{['Find purchase invoice INV-001','Show bank statement transactions','Find duplicate invoice numbers','Show ledger journal entries'].map(q=><button key={q} onClick={e=>submit(e,q)} disabled={busy||!ctx.auditId}>{q}<ArrowUpRight size={14}/></button>)}</div></div><div className="messages">{messages.map((m,i)=><div key={i} className="message-pair"><div className="user-message">{m.query}</div><div className="assistant-message"><span className="assistant-small"><Sparkles size={17}/></span><div><p>{m.answer}</p>{m.sources.map(s=><article className="retrieved-source" key={s.chunk_id}><div><button onClick={()=>ctx.setPreview(s.document_id)}><FileText size={15}/>{s.document_name}</button><small>v{s.version} · {s.page_number?'Page '+s.page_number:s.section_reference} · relevance {s.score}</small></div><pre>{s.text}</pre><SourceRefs refs={[s]}/></article>)}<small className="muted">{m.limitations}</small></div></div></div>)}</div><ErrorBox error={error}/><form className="query-form" onSubmit={submit}><Search size={20}/><input aria-label="Ask your audit question" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Ask about your audit evidence…" disabled={!ctx.auditId}/><button className="primary" disabled={busy||!query.trim()||!ctx.auditId}>{busy?<LoaderCircle className="spin" size={18}/>:<ArrowRight size={18}/>}</button></form><small className="assistant-disclaimer"><ShieldCheck size={13}/> Uploaded documents are treated as source data. Audit conclusions require human review.</small></section></>;}

function Evidence(){const ctx=React.useContext(Context);const [error,setError]=useState(''),[modal,setModal]=useState(false),[busy,setBusy]=useState(false);const {data,reload,error:loadError}=useLoad(()=>ctx.auditId?api('/evidence/'+ctx.auditId):Promise.resolve({requirements:[],mappings:[],requests:[],complete:0,total:0}),[ctx.auditId]);async function map(){setBusy(true);try{await api('/evidence/map',{method:'POST',body:{audit_id:Number(ctx.auditId)}});reload();ctx.notify('Evidence mapped. Review adequacy against source documents.')}catch(e){setError(e.message)}finally{setBusy(false)}}return <><Title title="Evidence mapping" description="Connect each audit requirement to the evidence that supports it."><button className="secondary" onClick={()=>setModal(true)} disabled={!ctx.auditId}><Plus size={16}/>Add requirement</button><button className="primary" disabled={!ctx.auditId||busy} onClick={map}><Workflow size={16}/>{busy?'Mapping…':'Map evidence'}</button></Title><ErrorBox error={error||loadError}/><div className="notice-inline"><ClipboardCheck size={17}/> Document presence maps coverage. An independent reviewer confirms whether the evidence is sufficient.</div>{data?<><div className="compact-stats"><span><b>{data.total}</b>Total requirements</span><span><b>{data.complete}</b>Reviewed complete</span><span><b>{data.requests.filter(r=>r.request_status==='Open').length}</b>Open evidence requests</span></div><section className="panel"><Table rows={data.requirements} columns={[{key:'requirement_name',label:'AUDIT REQUIREMENT',render:r=><div><b>{r.requirement_name}</b><small className="block muted">{r.required_evidence_type.join(' · ')}</small></div>},{key:'sources',label:'MAPPED SOURCES',render:r=><SourceRefs refs={data.mappings.filter(m=>m.requirement_id===r.id).map(m=>m.source_reference)}/>},{key:'status',label:'COMPLETENESS',render:r=><Badge>{r.status}</Badge>},{key:'review',label:'REVIEW',render:r=>['reviewer','administrator'].includes(ctx.user.role)&&<button className="text-link" onClick={async()=>{const comment=prompt('Document your adequacy review rationale:');if(!comment)return;try{await api(`/requirements/${r.id}/review`,{method:'POST',body:{approve:true,comment}});reload()}catch(e){setError(e.message)}}}>Confirm adequacy</button>}]} /></section><section className="panel space-top"><div className="panel-heading"><div><h2>Evidence requests</h2><p>Internal request list. No external communications are sent.</p></div></div><Table rows={data.requests} columns={[{key:'requested_document',label:'REQUESTED DOCUMENT'},{key:'requirement_id',label:'REQUIREMENT'},{key:'request_status',label:'STATUS',render:r=><Badge>{r.request_status}</Badge>}]} /></section></>:<Spinner/>}{modal&&<RequirementModal onClose={()=>setModal(false)} onDone={()=>{setModal(false);reload()}}/>}</>;}
function RequirementModal({onClose,onDone}){const ctx=React.useContext(Context);const settings=useLoad(()=>api('/settings'));const [error,setError]=useState('');return <Modal title="Add audit requirement" onClose={onClose}><ErrorBox error={error}/><form onSubmit={async e=>{e.preventDefault();const form=new FormData(e.target);try{await api('/requirements',{method:'POST',body:{audit_id:Number(ctx.auditId),requirement_name:form.get('name'),requirement_description:form.get('description'),required_evidence_type:form.getAll('categories')}});onDone()}catch(e){setError(e.message)}}}><label>Audit objective<input name="name" required/></label><label>Description<textarea name="description"/></label><label>Expected supporting evidence</label><div className="checkbox-grid">{settings.data?.categories.map(c=><label key={c}><input type="checkbox" name="categories" value={c}/>{c}</label>)}</div><button className="primary wide">Create requirement</button></form></Modal>;}

function Results({type}){const ctx=React.useContext(Context),isVerify=type==='verification';const [error,setError]=useState(''),[busy,setBusy]=useState(false),[filter,setFilter]=useState('');const result=useLoad(()=>ctx.auditId?api(`/${type}/results/${ctx.auditId}?per_page=100`):Promise.resolve({items:[]}),[ctx.auditId,type]);async function execute(){setBusy(true);setError('');try{await api(`/${type}/run/${ctx.auditId}`,{method:'POST'});result.reload();ctx.notify(isVerify?'Deterministic checks completed':'Reconciliation completed')}catch(e){setError(e.message)}finally{setBusy(false)}}const rows=result.data?.items||[];return <><Title title={isVerify?'Evidence verification':'Financial reconciliation'} description={isVerify?'Precise, deterministic checks with traceable source references.':'Compare financial records by reference, currency, date and amount.'}><button className="primary" onClick={execute} disabled={!ctx.auditId||busy}>{busy?<LoaderCircle className="spin" size={16}/>:<Play size={16}/>}Run {isVerify?'verification':'reconciliation'}</button></Title><div className="notice-inline"><ShieldCheck size={17}/>{isVerify?'A passing rule confirms only the stated check. It does not establish document authenticity.':'One-to-one matching uses exact decimal arithmetic. Ambiguous matches require human review.'}</div><ErrorBox error={error||result.error}/><section className="panel"><div className="toolbar"><h2>{rows.length} current results</h2><select aria-label="Result status" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">All statuses</option>{[...new Set(rows.map(r=>r.verification_status||r.status))].map(s=><option key={s}>{s}</option>)}</select></div>{result.data?<Table rows={rows.filter(r=>!filter||(r.verification_status||r.status)===filter)} columns={[{key:'type',label:'CHECK',render:r=><div><b>{r.verification_type||r.record_type}</b>{r.explanation&&<small className="explanation">{r.explanation}</small>}</div>},{key:'expected',label:'EXPECTED',render:r=>r.expected_value??r.expected_amount??'—'},{key:'actual',label:'ACTUAL',render:r=>r.actual_value??r.actual_amount??'—'},{key:'difference',label:'DIFFERENCE',render:r=><span className={r.difference&&Number(r.difference)!==0?'difference':''}>{r.difference??'—'}{r.currency?' '+r.currency:''}</span>},{key:'status',label:'RESULT',render:r=><Badge>{r.verification_status||r.status}</Badge>},{key:'sources',label:'SOURCE',render:r=><SourceRefs refs={r.evidence_references||[r.source_reference,r.matched_reference]}/>}]} empty="Run checks on the active audit's uploaded structured evidence."/>:<Spinner/>}</section></>;}
function Anomalies(){const ctx=React.useContext(Context);const {data,error}=useLoad(()=>ctx.auditId?api('/anomalies/'+ctx.auditId):Promise.resolve({indicators:[],sample_count:0}),[ctx.auditId]);return <><Title title="Anomaly detection" description="Explainable indicators to help focus your investigation."/><div className="notice-inline amber-notice"><TriangleAlert size={17}/> Anomalies are indicators for review, not evidence of fraud.</div><ErrorBox error={error}/>{data?<><div className="compact-stats"><span><b>{data.sample_count}</b>Eligible transaction rows</span><span><b>{data.indicators.length}</b>Indicators for investigation</span></div><section className="panel"><Table rows={data.indicators} columns={[{key:'kind',label:'INDICATOR'},{key:'amount',label:'AMOUNT',render:r=>r.amount?`${r.amount} ${r.currency}`:'—'},{key:'explanation',label:'EXPLANATION'},{key:'source',label:'EVIDENCE',render:r=><SourceRefs refs={[r.source,r.comparison]}/>}]} empty="No indicators detected in eligible rows. This does not establish an absence of risk."/></section><p className="muted">{data.method}</p></>:<Spinner/>}</>;}

const agents=['Document Collection Agent','Document Intelligence Agent','RAG Retrieval Agent','Audit Requirement Mapping Agent','Evidence Verification Agent','Financial Anomaly Detection Agent','Audit Analysis Agent','Audit Reporting Agent'];
function Agents(){const ctx=React.useContext(Context);const [busy,setBusy]=useState(false),[error,setError]=useState(''),[detail,setDetail]=useState(null);const result=useLoad(()=>ctx.auditId?api('/agents/logs/'+ctx.auditId+'?per_page=100'):Promise.resolve({items:[]}),[ctx.auditId]);const latest=result.data?.items[0]?.run_id;const logs=result.data?.items.filter(l=>l.run_id===latest)||[];async function execute(){setBusy(true);setError('');try{const d=await api('/agents/run/'+ctx.auditId,{method:'POST'});result.reload();ctx.refresh();ctx.notify(d.failed?'Workflow paused for extraction remediation':'Workflow complete. Human review checkpoint reached.')}catch(e){setError(e.message)}finally{setBusy(false)}}return <><Title title="Agent workspace" description="Eight specialized agents. One traceable, evidence-driven workflow."><button className="primary" disabled={busy||!ctx.auditId} onClick={execute}>{busy?<LoaderCircle className="spin" size={17}/>:<Play size={17}/>} {busy?'Running workflow…':'Run audit workflow'}</button></Title><ErrorBox error={error||result.error}/><div className="agent-summary"><div><span className="mode-tag"><i/>LangGraph orchestration</span><h2>Evidence to insight, step by step.</h2><p>Each agent works with actual documents and backend tools.<br/>Financial calculations use deterministic rules.</p></div><div className="agent-summary-stat"><strong>{logs.filter(l=>l.execution_status==='ok').length}<small> / 8</small></strong><span>agents completed in latest run</span></div></div><div className="agent-grid">{agents.map((name,i)=>{const log=logs.find(l=>l.agent_name===name);return <button className="panel agent-card" key={name} onClick={()=>log&&setDetail(log)}><div className="agent-card-top"><span className="agent-number">{String(i+1).padStart(2,'0')}</span><Badge>{busy?'Running':log?.execution_status||'Not run'}</Badge></div><Workflow size={24}/><h3>{name}</h3><p>{log?.output_summary?.summary||'Ready to process evidence from the active audit.'}</p><div className="agent-card-bottom"><span>{log?`${log.execution_time.toFixed(3)}s · ${log.model_version}`:'Deterministic tools'}</span><ArrowUpRight size={15}/></div></button>})}</div><div className="review-checkpoint"><span><ShieldCheck size={25}/></span><div><h3>Human review checkpoint</h3><p>The workflow prepares evidence and draft observations. An independent reviewer makes the final decision.</p></div><Link className="secondary" to="/review">Open review queue<ArrowRight size={16}/></Link></div><section className="panel space-top"><div className="panel-heading"><div><h2>Execution history</h2><p>Persisted agent outputs, timings and errors</p></div></div><Table rows={result.data?.items||[]} onRow={setDetail} columns={[{key:'agent_name',label:'AGENT'},{key:'run_id',label:'RUN',render:r=><code>{r.run_id.slice(0,10)}</code>},{key:'execution_status',label:'STATUS',render:r=><Badge>{r.execution_status}</Badge>},{key:'execution_time',label:'DURATION',render:r=>r.execution_time+'s'},{key:'created_at',label:'EXECUTED',render:r=>r.created_at.slice(0,19).replace('T',' ')}]}/></section>{detail&&<Modal title={detail.agent_name} onClose={()=>setDetail(null)}><pre className="json-view">{JSON.stringify(detail,null,2)}</pre></Modal>}</>;}

function Findings({review=false}){const ctx=React.useContext(Context);const [selected,setSelected]=useState(null),[error,setError]=useState(''),[create,setCreate]=useState(false);const {data,reload,error:loadError}=useLoad(()=>ctx.auditId?api('/findings/'+ctx.auditId+'?per_page=100'):Promise.resolve({items:[]}),[ctx.auditId,review]);return <><Title title={review?'Review & approvals':'Audit findings'} description={review?'Investigate the sources, document your judgment and approve the evidence.':'Evidence-linked observations, exceptions and documented decisions.'}>{review?<button className="primary" disabled={!ctx.auditId} onClick={async()=>{const comment=prompt('Document your final audit approval rationale:');if(!comment)return;try{await api(`/audits/${ctx.auditId}/approve`,{method:'POST',body:{comment}});ctx.notify('Audit approved by the assigned reviewer');ctx.refresh()}catch(e){setError(e.message)}}}><CheckCheck size={17}/>Approve audit</button>:<button className="primary" onClick={()=>setCreate(true)} disabled={!ctx.auditId}><Plus size={16}/>Add observation</button>}</Title><ErrorBox error={error||loadError}/>{review&&<div className="notice-inline"><ShieldCheck size={17}/> Review all findings and confirm evidence adequacy on the <Link to="/evidence">evidence mapping page</Link> before approving the audit.</div>}<section className="panel">{data?<Table rows={data.items} onRow={setSelected} columns={[{key:'finding_title',label:'FINDING',render:r=><div><b>{r.finding_title}</b><small className="explanation">{r.description}</small></div>},{key:'severity',label:'SEVERITY',render:r=><Badge>{r.severity}</Badge>},{key:'financial_impact',label:'INDICATED IMPACT',render:r=>r.financial_impact??'Undetermined'},{key:'status',label:'REVIEW STATUS',render:r=><Badge>{r.status}</Badge>},{key:'created_at',label:'CREATED',render:r=>r.created_at.slice(0,10)}]} empty="Run the workflow or add an auditor observation."/>:<Spinner/>}</section>{selected&&<FindingModal finding={selected} review={review} onClose={()=>setSelected(null)} onDone={()=>{reload();setSelected(null)}}/>}{create&&<Modal title="Add auditor observation" onClose={()=>setCreate(false)}><form onSubmit={async e=>{e.preventDefault();const form=new FormData(e.target);try{await api('/findings',{method:'POST',body:{audit_id:Number(ctx.auditId),finding_title:form.get('title'),description:form.get('description'),severity:form.get('severity'),recommendation:form.get('recommendation')}});setCreate(false);reload()}catch(e){setError(e.message);setCreate(false)}}}><label>Observation title<input name="title" required/></label><label>Description<textarea name="description" required/></label><label>Severity<select name="severity">{['Low','Medium','High','Critical'].map(s=><option key={s}>{s}</option>)}</select></label><label>Recommendation<textarea name="recommendation" required/></label><button className="primary wide">Save observation</button></form></Modal>}</>;}
function FindingModal({finding,review,onClose,onDone}){const [error,setError]=useState(''),[comment,setComment]=useState(''),[status,setStatus]=useState(review?'Accepted':'Pending Review');const comments=useLoad(()=>api(`/findings/${finding.id}/comments`));async function submit(e){e.preventDefault();try{await api(`/findings/${finding.id}${review?'/review':''}`,{method:review?'POST':'PUT',body:{status,comment}});onDone()}catch(e){setError(e.message)}}return <Modal title={finding.finding_title} onClose={onClose}><div className="row-actions"><Badge>{finding.severity}</Badge><Badge>{finding.status}</Badge></div><p>{finding.description}</p><SourceRefs refs={finding.evidence_references}/><h3>Recommended action</h3><p>{finding.recommendation}</p><h3>Review history</h3>{comments.data?.items.map(c=><div className="comment" key={c.id}><small>User #{c.user_id} · {c.created_at.slice(0,10)}</small><p>{c.comment}</p></div>)}<ErrorBox error={error}/><form onSubmit={submit}><label>{review?'Review decision':'Observation status'}<select value={status} onChange={e=>setStatus(e.target.value)}>{(review?['Accepted','Rejected','Resolved','Under Investigation']:['Open','Under Investigation','Pending Review']).map(s=><option key={s}>{s}</option>)}</select></label><label>Documented rationale<textarea required value={comment} onChange={e=>setComment(e.target.value)} placeholder="Explain the decision and evidence reviewed…"/></label><button className="primary wide">{review?'Save reviewer decision':'Save auditor comment'}</button></form></Modal>;}

function Reports(){const ctx=React.useContext(Context);const [busy,setBusy]=useState(''),[error,setError]=useState('');const {data,reload,error:loadError}=useLoad(()=>ctx.auditId?api('/reports?audit_id='+ctx.auditId):Promise.resolve({items:[]}),[ctx.auditId]);async function generate(format){setBusy(format);try{const d=await api('/reports/generate/'+ctx.auditId,{method:'POST',body:{format}});await download(`/reports/${d.id}/download`,`auditflow-report-${d.id}.${format}`);reload();ctx.notify('Evidence report generated')}catch(e){setError(e.message)}finally{setBusy('')}}return <><Title title="Audit reports" description="Download an immutable snapshot of evidence, checks and reviewer decisions."/><ErrorBox error={error||loadError}/><div className="report-options">{[['pdf','PDF evidence report','A structured narrative with scope, evidence references, verification results, missing evidence and review status.'],['xlsx','Excel evidence workbook','Evidence inventory, checks, reconciliations, missing evidence, findings and source mappings.']].map(([format,title,desc])=><section className="panel report-option" key={format}><span className="report-format">{format.toUpperCase()}</span><h2>{title}</h2><p>{desc}</p><button className="primary" disabled={!!busy||!ctx.auditId} onClick={()=>generate(format)}><Download size={17}/>{busy===format?'Generating…':'Generate '+format.toUpperCase()}</button></section>)}</div><div className="notice-inline"><ShieldCheck size={17}/> Reports remain marked DRAFT until an independent reviewer approves the audit.</div><section className="panel"><div className="panel-heading"><h2>Generated report snapshots</h2></div><Table rows={data?.items||[]} columns={[{key:'id',label:'REPORT',render:r=>'Evidence report #'+r.id},{key:'format',label:'FORMAT',render:r=>r.format.toUpperCase()},{key:'approved_by',label:'REVIEW',render:r=><Badge>{r.approved_by?'Approved':'Draft'}</Badge>},{key:'created_at',label:'CREATED',render:r=>r.created_at.slice(0,19).replace('T',' ')},{key:'download',label:'',render:r=><button className="text-link" onClick={()=>download(`/reports/${r.id}/download`,`auditflow-report-${r.id}.${r.format}`).catch(e=>setError(e.message))}><Download size={14}/>Download</button>}]}/></section></>;}
function SettingsPage(){const ctx=React.useContext(Context);const {data,error}=useLoad(()=>api('/settings'));const audit=useLoad(()=>ctx.auditId?api('/audits/'+ctx.auditId):Promise.resolve(null),[ctx.auditId]);const [message,setMessage]=useState('');return <><Title title="Workspace settings" description="Inspect processing capabilities and configure precise financial checks."/><ErrorBox error={error||message}/>{data&&<section className="panel settings-panel"><h2>Processing capabilities</h2><div className="settings-list">{[['Retrieval engine',data.retrieval],['LLM synthesis',data.llm_enabled?'Enabled':'Disabled · source excerpts only'],['OCR',data.ocr],['Malware scanning',data.malware_scan],['Upload limit',data.max_upload_mb+' MB per file'],['Environment',data.demo_mode?'Synthetic demo enabled':'Configured deployment']].map(([k,v])=><div key={k}><span>{k}</span><b>{v}</b></div>)}</div></section>}{audit.data&&<section className="panel settings-panel space-top"><h2>Audit matching rules</h2><p className="muted">Changing rules invalidates approval and requires another review.</p><form key={ctx.auditId} onSubmit={async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/audits/'+ctx.auditId,{method:'PUT',body:{settings:{tolerance:f.get('tolerance'),date_window:Number(f.get('date_window')),disabled_rules:audit.data.settings.disabled_rules||[]}}});ctx.notify('Audit matching rules updated')}catch(e){setMessage(e.message)}}}><div className="form-grid"><label>Amount tolerance<input name="tolerance" type="number" min="0" step="0.0001" defaultValue={audit.data.settings.tolerance}/></label><label>Date window (days)<input name="date_window" type="number" min="0" max="90" defaultValue={audit.data.settings.date_window}/></label></div><button className="primary">Save matching rules</button></form><button className="text-btn" onClick={async()=>{try{await api('/audits/'+ctx.auditId,{method:'PUT',body:{status:'In Progress'}});ctx.notify('Audit reopened for evidence changes')}catch(e){setMessage(e.message)}}}>Reopen audit for additional work</button></section>}</>;}
function UsersPage(){const {data,error,reload}=useLoad(()=>api('/users'));const [err,setErr]=useState('');return <><Title title="Team members" description="Manage user roles and independent review responsibilities."/><ErrorBox error={err||error}/><section className="panel"><Table rows={data?.items||[]} columns={[{key:'username',label:'NAME'},{key:'role',label:'ROLE',render:r=><select aria-label={'Role for '+r.username} value={r.role} onChange={async e=>{try{await api('/users/'+r.id,{method:'PUT',body:{role:e.target.value}});reload()}catch(e){setErr(e.message)}}}>{['auditor','reviewer','administrator'].map(x=><option key={x}>{x}</option>)}</select>}]} /></section></>;}
function Logs(){const {data,error}=useLoad(()=>api('/audit-logs?per_page=100'));return <><Title title="Audit trail" description="Trace who performed each recorded action."/><ErrorBox error={error}/><section className="panel"><Table rows={data?.items||[]} columns={[{key:'created_at',label:'TIMESTAMP',render:r=>r.created_at.slice(0,19)},{key:'user_id',label:'USER'},{key:'action',label:'ACTION'},{key:'resource_type',label:'RESOURCE',render:r=>r.resource_type+' #'+r.resource_id},{key:'details',label:'DETAILS',render:r=><code>{JSON.stringify(r.details)}</code>}]}/></section></>;}
function Notifications(){const {data,error,reload}=useLoad(()=>api('/notifications?per_page=100'));return <><Title title="Notifications" description="Evidence requests, processing issues and pending review work."/><ErrorBox error={error}/><section className="panel"><Table rows={data?.items||[]} columns={[{key:'notification_type',label:'TYPE'},{key:'message',label:'MESSAGE'},{key:'is_read',label:'STATUS',render:r=>r.is_read?'Read':<button className="text-link" onClick={async()=>{await api(`/notifications/${r.id}/read`,{method:'PUT'});reload()}}>Mark read</button>}]} /></section></>;}

if(document.getElementById('root'))createRoot(document.getElementById('root')).render(<BrowserRouter><Shell/></BrowserRouter>);
